// The Library's verse search: the committed word index (public/data/search-index.json,
// generated by server/seed/fetchSearchIndex.js) and the matching that runs over it.
//
// The index is ~1.3 MB (~260 KB gzipped), so it is fetched the first time search is
// opened — never with the reader — and kept for the rest of the session.
//
// Every word of the index is a word the mushaf draws: verses[ord - 1] lists the words
// of verse `ord` in position order, so word i sits at data-word-position i + 1. A hit
// is therefore reported as { ord, from, to } word positions and lands on the exact
// glyphs (the generator checks that alignment against the reader's own data).
//
// Matching, on normalised tokens (utils/quranSearchQuery.js):
//   - the query's words must appear CONSECUTIVELY, inside one verse;
//   - every word but the last must match a whole word; the LAST may be the start of
//     one, so results keep up while a word is still being typed;
//   - one Uthmani word can hold two tokens ("يا أيها" is position 1 of 2:104), so a
//     phrase can begin or end inside a word — the whole word is highlighted.
// Each place the phrase matches is one OCCURRENCE; a verse that matches twice
// contributes two.

import { arabicTokens } from '../utils/quranSearchQuery';

const INDEX_URL = '/data/search-index.json';

// Turn the index into flat typed arrays: one entry per TOKEN, in reading order.
// Normalising 77k words takes ~170 ms, so `pause` (a () => Promise) is awaited every
// BUILD_CHUNK verses to hand the main thread back — no single step is a long task,
// even on the first run, before the code has been optimised.
const BUILD_CHUNK = 250;
export const buildSearchEngine = async (json, { pause } = {}) => {
  const verses = json.verses;
  const vocab = new Map();   // token → id
  const vocabList = [];      // id → token
  const ids = [];            // token ids, the whole Quran in order
  const tokVerse = [];       // the verse (ord) each token is in
  const tokPos = [];         // the word position each token is in
  for (let v = 0; v < verses.length; v++) {
    if (pause && v > 0 && v % BUILD_CHUNK === 0) await pause();
    const words = verses[v].split('|');
    for (let w = 0; w < words.length; w++) {
      for (const tok of arabicTokens(words[w])) {
        let id = vocab.get(tok);
        if (id === undefined) { id = vocabList.length; vocab.set(tok, id); vocabList.push(tok); }
        ids.push(id);
        tokVerse.push(v + 1);
        tokPos.push(w + 1);
      }
    }
  }
  const tokens = Int32Array.from(ids);
  const verseOf = Uint16Array.from(tokVerse);
  const posOf = Uint16Array.from(tokPos);
  const wordCache = new Map();

  // { tokens, occurrences: [{ ord, from, to }] } in mushaf order.
  const search = (query) => {
    const q = arabicTokens(query);
    if (!q.length) return { tokens: q, occurrences: [] };
    const k = q.length;
    const exact = q.slice(0, -1).map((t) => vocab.get(t));
    if (exact.some((id) => id === undefined)) return { tokens: q, occurrences: [] };
    // Which vocabulary entries the last word can be (it may be half-typed).
    const last = q[k - 1];
    const lastOk = new Uint8Array(vocabList.length);
    let any = false;
    for (let i = 0; i < vocabList.length; i++) {
      if (vocabList[i].startsWith(last)) { lastOk[i] = 1; any = true; }
    }
    const occurrences = [];
    if (!any) return { tokens: q, occurrences };
    const n = tokens.length - k + 1;
    let prevKey = -1;
    outer: for (let j = 0; j < n; j++) {
      for (let i = 0; i < k - 1; i++) if (tokens[j + i] !== exact[i]) continue outer;
      if (!lastOk[tokens[j + k - 1]]) continue;
      const ord = verseOf[j];
      if (verseOf[j + k - 1] !== ord) continue;           // never across two verses
      const from = posOf[j];
      const to = posOf[j + k - 1];
      // Two tokens of ONE word can both match a one-word query; that word is one hit.
      const key = ord * 1e6 + from * 1e3 + to;
      if (key === prevKey) continue;
      prevKey = key;
      occurrences.push({ ord, from, to });
    }
    return { tokens: q, occurrences };
  };

  // The words of a verse, with their tashkeel, for the suggestion snippets.
  const words = (ord) => {
    let w = wordCache.get(ord);
    if (!w) { w = verses[ord - 1]?.split('|') ?? []; wordCache.set(ord, w); }
    return w;
  };

  return { search, words, size: { verses: verses.length, tokens: tokens.length, vocabulary: vocabList.length } };
};

// Let input and paint in between build steps: scheduler.yield() where the browser
// has it (it resumes ahead of other queued work), a macrotask otherwise.
const yieldToMain = () => (globalThis.scheduler?.yield
  ? globalThis.scheduler.yield()
  : new Promise((resolve) => setTimeout(resolve, 0)));

let loading = null;
// Fetch and build once; a failure is forgotten so the next open tries again.
export const loadSearchEngine = () => {
  if (!loading) {
    loading = fetch(INDEX_URL)
      .then((r) => { if (!r.ok) throw new Error(`search index ${r.status}`); return r.json(); })
      .then(async (json) => {
        const t0 = performance.now();
        const engine = await buildSearchEngine(json, { pause: yieldToMain });
        performance.measure?.('quran-search-build', { start: t0, end: performance.now() });
        return engine;
      })
      .catch((err) => { loading = null; throw err; });
  }
  return loading;
};
